def login_wolfram(email, password):
    driver.get("https://www.wolframalpha.com/input")

    # Navigate to the sign-in URL or trigger the sign-in button
    # Navigating directly to the Wolfram ID login endpoint saves time:
    driver.get("https://account.wolfram.com/auth/sign-in")

    # 1. Fill email
    email_input = wait.until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "input[type='email'], input#email"))
    )
    email_input.clear()
    email_input.send_keys(email)
    email_input.send_keys(Keys.RETURN)

    # 2. Fill password (Wolfram's auth portal sometimes displays password on the next step)
    password_input = wait.until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "input[type='password'], input#password"))
    )
    password_input.clear()
    password_input.send_keys(password)
    password_input.send_keys(Keys.RETURN)

    # 3. Wait for redirect back to Wolfram Alpha indicating successful authentication
    wait.until(EC.url_contains("wolframalpha.com"))

def open_eq_tab(equation, is_first=False):
    encoded_query = urllib.parse.quote_plus(equation)
    target_url = f"https://www.wolframalpha.com/input?i={encoded_query}"
    
    if not is_first:
        driver.switch_to.new_window("tab")
    driver.get(target_url)

